// Extract Fact Sheet
// Mode: Run Once for All Items
// Input: the output of the n8n "Get a workflow" node. One item per workflow:
//        the project first, then its sub-workflows.
//
// Rule of this node: it only ever COPIES things from an allowlist.
// It never passes the whole workflow on. Anything not named here is dropped.

const ALLOWED_PARAMETERS = [
  'resource', 'operation', 'model', 'httpMethod',
  'authentication', 'mode', 'aggregate', 'respondWith', 'limit'
];

// Tags that belong to the portfolio machinery and mean nothing to a reader.
const MACHINERY_TAGS = ['Portfolio', 'Portfolio Part'];

const EXECUTE_WORKFLOW_TYPE = 'n8n-nodes-base.executeWorkflow';

// A value that starts with "=" is an n8n expression (a small piece of code),
// not a plain fact. Expressions are never copied.
function isExpression(value) {
  return typeof value === 'string' && value.startsWith('=');
}

// Prompt text typed in expression mode starts with "=". The "=" is only a marker,
// so it is removed before the text goes anywhere.
function removeExpressionMarker(text) {
  if (text.startsWith('=')) {
    return text.slice(1);
  }
  return text;
}

// Positions must be two plain numbers, otherwise they fall back to 0, 0.
function cleanPosition(position) {
  const isPair = Array.isArray(position) && position.length === 2;
  if (isPair && typeof position[0] === 'number' && typeof position[1] === 'number') {
    return [position[0], position[1]];
  }
  return [0, 0];
}

// Reads the identifier of the workflow that an "Execute Workflow" node calls.
// Returns an empty text when it cannot be known for sure (for example, when it is
// calculated by an expression, or loaded from a file or a web address).
function readCalledWorkflowId(params) {
  if (params.source !== undefined && params.source !== 'database') {
    return '';
  }
  let value = params.workflowId;
  if (value && typeof value === 'object') {
    value = value.value;
  }
  if (typeof value !== 'string' || value === '' || value.startsWith('=')) {
    return '';
  }
  return value;
}

const results = [];

for (const item of $input.all()) {
  const wf = item.json;

  const nodes = [];
  const prompts = [];
  const stickyNotes = [];
  const calledWorkflows = [];
  const knownNodeNames = {};

  // 1. Nodes, sticky notes and prompts
  for (const node of wf.nodes || []) {
    const params = node.parameters || {};
    const fullType = typeof node.type === 'string' ? node.type : '';

    if (fullType === '') {
      continue; // a node without a type cannot be drawn or described
    }

    if (fullType === 'n8n-nodes-base.stickyNote') {
      const content = typeof params.content === 'string' ? params.content : '';
      if (content.trim() !== '') {
        stickyNotes.push(content);
      }
      continue; // sticky notes are not nodes of the diagram
    }

    // Allowlisted parameters: only plain values, text at most 100 characters
    const details = {};
    for (const key of ALLOWED_PARAMETERS) {
      let value = params[key];
      if (key === 'model' && value && typeof value === 'object') {
        value = value.value;
      }
      const isText = typeof value === 'string' && value.length <= 100 && !isExpression(value);
      const isSimple = typeof value === 'number' || typeof value === 'boolean';
      if (isText || isSimple) {
        details[key] = value;
      }
    }

    knownNodeNames[node.name] = true;

    nodes.push({
      name: node.name,
      type: fullType.split('.').pop(),
      fullType: fullType,
      typeVersion: typeof node.typeVersion === 'number' ? node.typeVersion : 1,
      position: cleanPosition(node.position),
      disabled: node.disabled === true,
      details: details
    });

    // Which workflow does this node call? Kept outside the fact sheet: Combine Fact Sheets
    // uses it to link the workflows together and then drops it.
    if (fullType === EXECUTE_WORKFLOW_TYPE) {
      const calledId = readCalledWorkflowId(params);
      if (calledId !== '') {
        calledWorkflows.push({ nodeName: node.name, workflowId: calledId });
      }
    }

    // Prompts of language-model nodes (free text lane)
    if (fullType.startsWith('@n8n/n8n-nodes-langchain.')) {
      if (typeof params.text === 'string' && params.text.trim() !== '') {
        prompts.push({ node: node.name, kind: 'text', text: removeExpressionMarker(params.text) });
      }
      const options = params.options || {};
      if (typeof options.systemMessage === 'string' && options.systemMessage.trim() !== '') {
        prompts.push({ node: node.name, kind: 'systemMessage', text: removeExpressionMarker(options.systemMessage) });
      }
    }
  }

  // 2. Connections (only between nodes that are in the list above)
  const connections = [];
  for (const [fromName, outputs] of Object.entries(wf.connections || {})) {
    if (!knownNodeNames[fromName]) {
      continue;
    }
    for (const [connectionType, branches] of Object.entries(outputs)) {
      for (let outputIndex = 0; outputIndex < branches.length; outputIndex++) {
        const targets = branches[outputIndex] || [];
        for (const target of targets) {
          if (!knownNodeNames[target.node]) {
            continue;
          }
          connections.push({
            from: fromName,
            to: target.node,
            type: connectionType,
            outputIndex: outputIndex,
            inputIndex: typeof target.index === 'number' ? target.index : 0
          });
        }
      }
    }
  }

  // 3. Tags, without the portfolio machinery tags. A tag can be an object or plain text.
  const tags = [];
  for (const tag of wf.tags || []) {
    const tagName = typeof tag === 'string' ? tag : tag && tag.name;
    if (typeof tagName === 'string' && tagName !== '' && !MACHINERY_TAGS.includes(tagName)) {
      tags.push(tagName);
    }
  }

  results.push({
    json: {
      workflowId: wf.id,
      name: wf.name,
      lastUpdatedAt: wf.updatedAt,
      hasNotes: stickyNotes.length > 0,
      calledWorkflows: calledWorkflows,
      factSheet: { tags: tags, nodes: nodes, connections: connections },
      freeText: { stickyNotes: stickyNotes, prompts: prompts }
    }
  });
}

return results;

const sampleRows = $input.all();

const samples = [];
for (const row of sampleRows) {
  samples.push(row.json.samples);
}

const cleanedData = $('Is Safe').first().json.redacted;

// The code address of the project: one plain line in a sticky note,
// like "GitHub: https://github.com/name/repository". Only that exact shape is accepted.
let githubAddress = '';
const notes = cleanedData.freeText && Array.isArray(cleanedData.freeText.stickyNotes) ? cleanedData.freeText.stickyNotes : [];
for (const note of notes) {
  const text = typeof note.text === 'string' ? note.text : '';
  for (const line of text.split('\n')) {
    const match = line.trim().match(/^GitHub:\s*(https:\/\/github\.com\/[A-Za-z0-9._-]+\/[A-Za-z0-9._-]+)$/);
    if (match && githubAddress === '') {
      githubAddress = match[1];
    }
  }
}

return [{
  json: {
    samples: samples.join('\n\n---\n\n'),
    cleanedData: cleanedData,
    githubAddress: githubAddress
  }
}];

// Validate Page
// Mode: Run Once for All Items
// Input: the output of the writer chain, shaped like { output: { title, summary, blocks } }.
//
// Rule of this node: nothing the writer produced is trusted. It is checked, cleaned,
// and only the cleaned copy continues.

const MAX_TITLE_LENGTH = 120;
const MAX_SUMMARY_LENGTH = 500;
const MAX_BLOCK_TEXT_LENGTH = 8000;
const MAX_BLOCKS = 12;

const written = $input.first().json.output || {};

// The fact sheet is the only source of truth for node names.
const factSheet = $('Prepare Writer Input').first().json.cleanedData.factSheet;

const knownNodeNames = {};
for (const node of factSheet.nodes) {
  knownNodeNames[node.name] = true;
}

const problems = [];
const droppedNodeNames = [];

function isFilledText(value) {
  return typeof value === 'string' && value.trim() !== '';
}

// 1. Title and summary
let title = '';
if (isFilledText(written.title)) {
  title = written.title.trim();
  if (title.length > MAX_TITLE_LENGTH) {
    problems.push('The title is longer than ' + MAX_TITLE_LENGTH + ' characters');
  }
} else {
  problems.push('The title is missing');
}

let summary = '';
if (isFilledText(written.summary)) {
  summary = written.summary.trim();
  if (summary.length > MAX_SUMMARY_LENGTH) {
    problems.push('The summary is longer than ' + MAX_SUMMARY_LENGTH + ' characters');
  }
} else {
  problems.push('The summary is missing');
}

// 2. Blocks
const blocks = Array.isArray(written.blocks) ? written.blocks : [];
if (blocks.length > MAX_BLOCKS) {
  problems.push('There are more than ' + MAX_BLOCKS + ' blocks');
}

const cleanBlocks = [];
for (let i = 0; i < blocks.length; i++) {
  const block = blocks[i] || {};
  const blockNumber = i + 1;

  if (!isFilledText(block.text)) {
    problems.push('Block ' + blockNumber + ' has no text');
    continue;
  }
  if (block.text.length > MAX_BLOCK_TEXT_LENGTH) {
    problems.push('Block ' + blockNumber + ' is longer than ' + MAX_BLOCK_TEXT_LENGTH + ' characters');
    continue;
  }

  const heading = typeof block.heading === 'string' ? block.heading.trim() : '';

  // Keep only node names that really exist in the fact sheet
  const nodeNames = [];
  const listedNames = Array.isArray(block.nodes) ? block.nodes : [];
  for (const name of listedNames) {
    if (typeof name === 'string' && knownNodeNames[name] === true) {
      if (!nodeNames.includes(name)) {
        nodeNames.push(name);
      }
    } else {
      droppedNodeNames.push(String(name));
    }
  }

  cleanBlocks.push({
    heading: heading,
    text: block.text.trim(),
    nodes: nodeNames
  });
}

if (cleanBlocks.length === 0) {
  problems.push('The page has no usable block');
}

return [{
  json: {
    valid: problems.length === 0,
    problems: problems,
    droppedNodeNames: droppedNodeNames,
    factSheet: factSheet,
    page: {
      title: title,
      summary: summary,
      blocks: cleanBlocks
    }
  }
}];

// Build Block Diagrams
// Mode: Run Once for All Items
// Input: the output of Validate Page: { valid, page, factSheet, ... }
//
// For every block that lists nodes, this builds a small workflow containing ONLY those
// nodes and the connections between them. It is built from the cleaned fact sheet, so it
// has no credentials, no pinned data, and only allowlisted parameters.
// This small workflow is the only thing that may ever be given to a diagram viewer.
//
// The nodes are also tidied: the positions in the original workflows are spread over a huge
// canvas, so a small selection of nodes would be drawn tiny and far apart. Here the empty
// space is removed, and the nodes of each workflow are kept together.

const COLUMN_WIDTH = 224;
const ROW_HEIGHT = 120;
const SAME_COLUMN_DISTANCE = 100; // nodes closer than this (sideways) share a column
const SAME_ROW_DISTANCE = 60;     // nodes closer than this (up and down) share a row
const MAX_OVERVIEW_NODES = 100;   // a bigger system gets no overview: it would be unreadable
const LABEL_HEIGHT = 80;          // the label above each workflow in the overview

const input = $input.first().json;
const page = input.page;
const factSheet = input.factSheet;

const nodesByName = {};
const workflowOrder = []; // the workflows, in the order they appear in the fact sheet
for (const node of factSheet.nodes) {
  nodesByName[node.name] = node;
  if (!workflowOrder.includes(node.workflow)) {
    workflowOrder.push(node.workflow);
  }
}

// Turns a list of numbers into slot numbers 0, 1, 2...
// Numbers that are close together share a slot, and the empty space between them disappears.
function findSlots(values, maxDistance) {
  const sorted = values.slice().sort(function (a, b) { return a - b; });
  const slotByValue = {};
  let slot = 0;
  let previous = null;
  for (const value of sorted) {
    if (previous !== null && value - previous > maxDistance) {
      slot++;
    }
    slotByValue[value] = slot;
    previous = value;
  }
  return slotByValue;
}

// Gives new positions to the nodes of ONE workflow, starting at column 0, row 0.
// Returns the number of rows used.
function tidyGroup(sourceNodes, firstRow, positionsByName) {
  const xValues = [];
  const yValues = [];
  for (const node of sourceNodes) {
    xValues.push(node.position[0]);
    yValues.push(node.position[1]);
  }
  const columns = findSlots(xValues, SAME_COLUMN_DISTANCE);
  const rows = findSlots(yValues, SAME_ROW_DISTANCE);

  const taken = {};
  let lastRow = 0;
  for (const node of sourceNodes) {
    const column = columns[node.position[0]];
    let row = rows[node.position[1]];
    // Two nodes must never land in the same place: push the later one down
    while (taken[column + ',' + row] === true) {
      row++;
    }
    taken[column + ',' + row] = true;
    positionsByName[node.name] = [column * COLUMN_WIDTH, (firstRow + row) * ROW_HEIGHT];
    if (row > lastRow) {
      lastRow = row;
    }
  }
  return lastRow + 1;
}

function tidyPositions(nodeNames) {
  const positionsByName = {};
  const groupStarts = []; // where each workflow starts, for the labels of the overview
  let nextRow = 0;
  for (const workflow of workflowOrder) {
    const groupNodes = [];
    for (const name of nodeNames) {
      const source = nodesByName[name];
      if (source && source.workflow === workflow) {
        groupNodes.push(source);
      }
    }
    if (groupNodes.length === 0) {
      continue;
    }
    groupStarts.push({ workflow: workflow, firstRow: nextRow });
    const rowsUsed = tidyGroup(groupNodes, nextRow, positionsByName);
    nextRow = nextRow + rowsUsed + 1; // one empty row between workflows
  }
  return { positions: positionsByName, groupStarts: groupStarts };
}

function buildDiagram(nodeNames, addLabels) {
  const included = {};
  const diagramNodes = [];
  const tidy = tidyPositions(nodeNames);
  const positions = tidy.positions;

  for (const name of nodeNames) {
    const source = nodesByName[name];
    if (!source) {
      continue;
    }
    included[name] = true;

    const diagramNode = {
      parameters: source.details,
      id: 'node-' + (diagramNodes.length + 1),
      name: source.name,
      type: source.fullType,
      typeVersion: source.typeVersion,
      position: positions[name]
    };
    if (source.disabled === true) {
      diagramNode.disabled = true;
    }
    diagramNodes.push(diagramNode);
  }

  // In the overview, a sticky note in the empty row above each workflow tells which one it is
  if (addLabels === true) {
    for (const start of tidy.groupStarts) {
      diagramNodes.push({
        parameters: { content: '### ' + start.workflow, width: 320, height: LABEL_HEIGHT, color: 5 },
        id: 'node-' + (diagramNodes.length + 1),
        name: 'Label ' + start.workflow,
        type: 'n8n-nodes-base.stickyNote',
        typeVersion: 1,
        position: [0, (start.firstRow - 1) * ROW_HEIGHT + 20]
      });
    }
  }

  // Keep only the connections where both ends are in this diagram
  const diagramConnections = {};
  for (const connection of factSheet.connections) {
    if (included[connection.from] !== true || included[connection.to] !== true) {
      continue;
    }
    if (!diagramConnections[connection.from]) {
      diagramConnections[connection.from] = {};
    }
    if (!diagramConnections[connection.from][connection.type]) {
      diagramConnections[connection.from][connection.type] = [];
    }

    // Each output branch is a list of targets. Fill any gap with an empty list.
    const branches = diagramConnections[connection.from][connection.type];
    while (branches.length <= connection.outputIndex) {
      branches.push([]);
    }
    branches[connection.outputIndex].push({
      node: connection.to,
      type: connection.type,
      index: connection.inputIndex
    });
  }

  return { nodes: diagramNodes, connections: diagramConnections };
}

// The overview: every node of every workflow, tidied, with a label for each workflow
const allNodeNames = [];
for (const node of factSheet.nodes) {
  allNodeNames.push(node.name);
}
let overview = null;
if (allNodeNames.length > 0 && allNodeNames.length <= MAX_OVERVIEW_NODES) {
  overview = buildDiagram(allNodeNames, true);
}

// Plain numbers for the page, counted here and not written by the model
const stats = { workflows: workflowOrder.length, nodes: allNodeNames.length };

const blocks = [];
for (const block of page.blocks) {
  let diagram = null;
  if (block.nodes.length > 0) {
    diagram = buildDiagram(block.nodes);
  }
  blocks.push({
    heading: block.heading,
    text: block.text,
    nodes: block.nodes,
    diagram: diagram
  });
}

return [{
  json: {
    page: {
      title: page.title,
      summary: page.summary,
      overview: overview,
      stats: stats,
      blocks: blocks
    }
  }
}];

// Build Page Html
// Mode: Run Once for All Items
// Input: the output of Build Block Diagrams: { page: { title, summary, blocks } }
//
// Rule of this node: everything the writer produced is plain text, never markup.
// Every piece of text goes through escapeHtml before it is placed in the page.
// The only markup in the result is the markup written in this file.

const DIAGRAM_SCRIPT_ADDRESS = 'https://cdn.jsdelivr.net/npm/@n8n_io/n8n-demo-component@1.0.20/n8n-demo.bundled.js';

const page = $input.first().json.page;

// Turns the five characters that can break out of text or an attribute into safe codes.
function escapeHtml(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// A block of text becomes one paragraph per blank-line-separated piece.
function buildParagraphs(text) {
  const pieces = text.split(/\n\s*\n/);
  let html = '';
  for (const piece of pieces) {
    if (piece.trim() !== '') {
      html += '<p>' + escapeHtml(piece.trim()) + '</p>\n';
    }
  }
  return html;
}

let body = '';
body += '<script type="module" src="' + DIAGRAM_SCRIPT_ADDRESS + '"></script>\n';
body += '<p class="lp-summary">' + escapeHtml(page.summary) + '</p>\n';

// The overview comes first: the whole system in one picture, with two plain numbers.
// The numbers are counted by the workflow, not written by the model.
if (page.overview !== null) {
  const workflowWord = page.stats.workflows === 1 ? ' workflow' : ' workflows';
  body += '<section class="lp-block lp-overview">\n';
  body += '<h2>The whole machine, all at once</h2>\n';
  body += '<p class="lp-stats">' + page.stats.workflows + workflowWord + ' · ' + page.stats.nodes + ' nodes</p>\n';
  body += '<n8n-demo style="--n8n-workflow-min-height: 800px" workflow="' + escapeHtml(JSON.stringify(page.overview)) + '"></n8n-demo>\n';
  body += '</section>\n';
}

for (const block of page.blocks) {
  body += '<section class="lp-block">\n';
  if (block.heading !== '') {
    body += '<h2>' + escapeHtml(block.heading) + '</h2>\n';
  }
  body += buildParagraphs(block.text);
  if (block.diagram !== null) {
    const diagramText = JSON.stringify(block.diagram);
    body += '<n8n-demo workflow="' + escapeHtml(diagramText) + '"></n8n-demo>\n';
  }
  body += '</section>\n';
}

const githubAddress = $('Prepare Writer Input').first().json.githubAddress;
if (typeof githubAddress === 'string' && githubAddress !== '') {
  body += '<section class="lp-block lp-code">\n';
  body += '<h2>Get the code</h2>\n';
  body += '<p><a class="lp-github" href="' + escapeHtml(githubAddress) + '" target="_blank" rel="noopener">See this project on GitHub</a></p>\n';
  body += '</section>\n';
}

// One Custom HTML block, so the WordPress editor shows it cleanly instead of as an old-style block.
const content = '<!-- wp:html -->\n' + body + '<!-- /wp:html -->';

// The title and the excerpt are plain text fields in WordPress. Removing the angle brackets
// makes it impossible for them to carry markup, and leaves every other character untouched.
function removeAngleBrackets(text) {
  return String(text).replace(/[<>]/g, '');
}

return [{
  json: {
    title: removeAngleBrackets(page.title),
    excerpt: removeAngleBrackets(page.summary),
    content: content
  }
}];

// Choose Page Action
// Mode: Run Once for All Items
// Input: the rows found in the table for this project (can be empty).
//
// Decides whether the page is created or updated, and collects everything the
// WordPress step needs into one item. This node and Build Published Result are the
// only places in Process Project that read the original request.

// The safety check is real now (pattern scan and reviewing model), so pages are published.
// Change this back to 'draft' to stop publishing without touching anything else.
const PAGE_STATUS = 'publish';
// The page "Automations" in WordPress. Every project page becomes a child of it.
const PARENT_PAGE_ID = 597;
const request = $('Receive Project Details').first().json;
const page = $('Build Page Html').first().json;
const savedRows = $input.all();

// A page identifier in the request wins. Otherwise use the one saved in the table,
// which is how a returning project finds its old page.
let wordpressId = '';
if (typeof request.wordpressId === 'string' && request.wordpressId.trim() !== '') {
  wordpressId = request.wordpressId.trim();
} else {
  for (const row of savedRows) {
    const savedId = row.json.wordpressId;
    if (typeof savedId === 'string' && savedId.trim() !== '') {
      wordpressId = savedId.trim();
      break;
    }
  }
}

let action = 'create';
if (wordpressId !== '') {
  action = 'update';
}

return [{
  json: {
    action: action,
    wordpressId: wordpressId,
    pageStatus: PAGE_STATUS,
    parentId: PARENT_PAGE_ID,
    excerpt: page.excerpt,
    title: page.title,
    content: page.content,
    workflowId: request.workflowId,
    name: request.name,
    lastUpdatedAt: request.lastUpdatedAt
  }
}];

