// List Family Ids
// Turns the request into one item per workflow to read: the project, then its parts.

const request = $input.first().json;

const items = [{ json: { workflowId: request.workflowId } }];

const partIds = typeof request.partIds === 'string' ? request.partIds : '';
for (const id of partIds.split(',')) {
  const cleanId = id.trim();
  if (cleanId !== '' && cleanId !== request.workflowId) {
    items.push({ json: { workflowId: cleanId } });
  }
}

return items;

// Combine Fact Sheets
// Mode: Run Once for All Items
// Input: one fact sheet per workflow, from Extract Fact Sheet: the project and its sub-workflows.
// Output: ONE fact sheet shaped like the fact sheet of a single workflow, so every node
//         after this one works unchanged.
//
// - The project keeps its node names. Sub-workflow nodes are renamed "Workflow name / Node name"
//   (the start that all the workflow names share is left out),
//   because node names must be unique and many workflows share names like "Edit Fields".
// - Sub-workflows are placed below the project, so the drawing does not overlap.
// - Where a node calls a sub-workflow, a connection is added from that node to the first
//   node after the sub-workflow's trigger. It is marked kind: "sub-workflow call".
//
// Rule of this node: workflow identifiers are used here to link calls to sub-workflows,
// and are dropped afterwards. They do not leave this node.

const GAP_BETWEEN_WORKFLOWS = 200;
const EXECUTE_WORKFLOW_TRIGGER_TYPE = 'n8n-nodes-base.executeWorkflowTrigger';

const mainWorkflowId = $('Receive Project Details').first().json.workflowId;

// 1. Find the project among the sheets. The others are its sub-workflows.
let mainSheet = null;
const subSheets = [];
for (const item of $input.all()) {
  if (item.json.workflowId === mainWorkflowId) {
    mainSheet = item.json;
  } else {
    subSheets.push(item.json);
  }
}
if (mainSheet === null) {
  throw new Error('The project is missing from the fact sheets');
}

const orderedSheets = [mainSheet];
for (const sheet of subSheets) {
  orderedSheets.push(sheet);
}

const sheetsById = {};
for (const sheet of orderedSheets) {
  sheetsById[sheet.workflowId] = sheet;
}

// 2. Give every workflow a short label that is unique.
// Names often share a start, like "Living Portfolio - Sync" and "Living Portfolio - Unpublish".
// That shared start is removed, so "Living Portfolio - Unpublish" becomes "Unpublish".
function shortenName(name) {
  const separator = ' - ';
  const separatorPosition = mainSheet.name.indexOf(separator);
  if (separatorPosition === -1) {
    return name;
  }
  const sharedStart = mainSheet.name.slice(0, separatorPosition + separator.length);
  if (name.startsWith(sharedStart) && name.length > sharedStart.length) {
    return name.slice(sharedStart.length);
  }
  return name;
}

const labelsById = {};
const usedLabels = {};
for (const sheet of orderedSheets) {
  const shortName = shortenName(sheet.name);
  let label = shortName;
  let counter = 2;
  while (usedLabels[label] === true) {
    label = shortName + ' (' + counter + ')';
    counter++;
  }
  usedLabels[label] = true;
  labelsById[sheet.workflowId] = label;
}

function newNodeName(sheet, nodeName) {
  if (sheet.workflowId === mainSheet.workflowId) {
    return nodeName;
  }
  return labelsById[sheet.workflowId] + ' / ' + nodeName;
}

// 3. Top-left corner and lowest point of a list of nodes
function findTopLeft(nodes) {
  if (nodes.length === 0) {
    return [0, 0];
  }
  let smallestX = nodes[0].position[0];
  let smallestY = nodes[0].position[1];
  for (const node of nodes) {
    if (node.position[0] < smallestX) {
      smallestX = node.position[0];
    }
    if (node.position[1] < smallestY) {
      smallestY = node.position[1];
    }
  }
  return [smallestX, smallestY];
}

const mainTopLeft = findTopLeft(mainSheet.factSheet.nodes);

// 4. Copy the nodes, with new names and new positions
const combinedNodes = [];
let lowestY = mainTopLeft[1];

for (const sheet of orderedSheets) {
  const topLeft = findTopLeft(sheet.factSheet.nodes);
  let shiftX = 0;
  let shiftY = 0;
  if (sheet.workflowId !== mainSheet.workflowId) {
    shiftX = mainTopLeft[0] - topLeft[0];
    shiftY = lowestY + GAP_BETWEEN_WORKFLOWS - topLeft[1];
  }

  for (const node of sheet.factSheet.nodes) {
    const newY = node.position[1] + shiftY;
    combinedNodes.push({
      name: newNodeName(sheet, node.name),
      workflow: labelsById[sheet.workflowId],
      type: node.type,
      fullType: node.fullType,
      typeVersion: node.typeVersion,
      position: [node.position[0] + shiftX, newY],
      disabled: node.disabled,
      details: node.details
    });
    if (newY > lowestY) {
      lowestY = newY;
    }
  }
}

// 5. Copy the connections inside each workflow, with the new names
const combinedConnections = [];
for (const sheet of orderedSheets) {
  for (const connection of sheet.factSheet.connections) {
    combinedConnections.push({
      from: newNodeName(sheet, connection.from),
      to: newNodeName(sheet, connection.to),
      type: connection.type,
      outputIndex: connection.outputIndex,
      inputIndex: connection.inputIndex
    });
  }
}

// 6. Link every call to the sub-workflow it calls
for (const caller of orderedSheets) {
  for (const call of caller.calledWorkflows || []) {
    const child = sheetsById[call.workflowId];
    if (!child || child.workflowId === caller.workflowId) {
      continue; // not part of this family
    }

    // The trigger of the sub-workflow, and the nodes it leads to
    let triggerName = '';
    for (const node of child.factSheet.nodes) {
      if (node.fullType === EXECUTE_WORKFLOW_TRIGGER_TYPE) {
        triggerName = node.name;
        break;
      }
    }
    if (triggerName === '') {
      continue;
    }

    for (const connection of child.factSheet.connections) {
      if (connection.from === triggerName && connection.type === 'main') {
        combinedConnections.push({
          from: newNodeName(caller, call.nodeName),
          to: newNodeName(child, connection.to),
          type: 'main',
          outputIndex: 0,
          inputIndex: connection.inputIndex,
          kind: 'sub-workflow call'
        });
      }
    }
  }
}

// 6b. Free text: notes say which workflow they belong to, prompts use the new node names
const stickyNotes = [];
const prompts = [];
let hasNotes = false;
for (const sheet of orderedSheets) {
  if (sheet.hasNotes === true) {
    hasNotes = true;
  }
  for (const text of sheet.freeText.stickyNotes) {
    stickyNotes.push({ workflow: labelsById[sheet.workflowId], text: text });
  }
  for (const prompt of sheet.freeText.prompts) {
    prompts.push({
      node: newNodeName(sheet, prompt.node),
      kind: prompt.kind,
      text: prompt.text
    });
  }
}

const subWorkflows = [];
for (const sheet of subSheets) {
  subWorkflows.push(labelsById[sheet.workflowId]);
}

// 7. The result. No workflow identifiers.
return [{
  json: {
    name: mainSheet.name,
    hasNotes: hasNotes,
    subWorkflows: subWorkflows,
    factSheet: {
      tags: mainSheet.factSheet.tags,
      nodes: combinedNodes,
      connections: combinedConnections
    },
    freeText: { stickyNotes: stickyNotes, prompts: prompts }
  }
}];
